const l=s=>s.split('|');
export const FILAMENT_TASKS=['feed-clear','fragment','coldpull-manual'];
const clog='https://help.prusa3d.com/article/clogged-nozzle-core-one-core-one-l-xl-mk4-s-mk3-9-s_411823#procedures-that-require-nozzle-heating';
const manual='https://help.prusa3d.com/article/cold-pull-31702-core-one-35702-core-one-l_930551#manual-cold-pull';
export const FILAMENT_COPY={
 feed:l('PLAを入口に合わせ、真下へ送る|Align PLA with the inlet and feed straight down|Vyrovnat PLA se vstupem a zavést přímo dolů|PLA am Einlass ausrichten und gerade nach unten schieben'),
 withdraw:l('試したPLAを真上へ抜く。抜けなければ止める|Withdraw the test PLA straight up; stop if it will not move|Vytáhnout zkušební PLA přímo vzhůru; pokud nejde, zastavit|Test-PLA gerade nach oben herausziehen; bei Widerstand stoppen'),
 fragment:l('見えている端をペンチでつかみ、真上へ少しずつ抜く|Grip the visible end with pliers and withdraw gradually straight up|Uchopit viditelný konec kleštěmi a postupně táhnout přímo vzhůru|Sichtbares Ende mit Zange greifen und schrittweise gerade nach oben ziehen'),
 push:l('温度到達後、PLAを手で真下へ押す。実機の吐出を確認する|After reaching temperature push PLA straight down by hand; check actual extrusion|Po dosažení teploty ručně tlačit PLA přímo dolů; ověřit skutečnou extruzi|Nach Erreichen der Temperatur PLA von Hand gerade nach unten schieben; tatsächlichen Austritt prüfen'),
 pull:l('100°CでNextruderを支え、ペンチで一定に真上へ抜く|At 100 °C support the Nextruder and pull steadily straight up with pliers|Při 100 °C podepřít Nextruder a kleštěmi rovnoměrně táhnout přímo vzhůru|Bei 100 °C Nextruder stützen und mit Zange gleichmäßig gerade nach oben ziehen'),
 reference:l('水色は直径1.75mmの作業材の参考表示です。溶融・吐出量や押す力を示すものではありません。|Blue shows a 1.75 mm working-material reference; it does not predict melt volume, extrusion or force.|Modrá znázorňuje pracovní materiál průměru 1,75 mm, nikoli objem taveniny, extruzi či sílu.|Blau zeigt eine Arbeitsmaterial-Referenz mit 1,75 mm Durchmesser, keine Schmelzmenge, Extrusion oder Kraft.'),
 success:l('流れが戻り、試したPLAも抜けた → 締め戻す|Flow restored and test PLA removed → reassemble|Tok obnoven a zkušební PLA vyjmuto → sestavit|Fluss wiederhergestellt und Test-PLA entfernt → zusammenbauen'),
 failure:l('流れが戻らない／PLAが抜けない → 詰まりの分岐へ|No flow / PLA will not withdraw → blockage checks|Bez toku / PLA nelze vytáhnout → kontrola ucpání|Kein Fluss / PLA nicht entfernbar → Verstopfung prüfen')
};
export function completeFilamentMaintenance(tasks){
 const feed=tasks.find(t=>t.id==='feed-clear'),fragment=tasks.find(t=>t.id==='fragment');
 for(const task of tasks.filter(t=>FILAMENT_TASKS.includes(t.id)))task.filamentMaintenance=true;
 feed.revision++;
 feed.steps[4]={...feed.steps[4],id:'feed-new-pla',body:l('入口・継手とアイドラーは開いたままです。温度到達後2分待ってから、新しいPLAを上からまっすぐ送り、実機で吐出するか確認します。この段階では締め戻しません。流れが戻らない場合は押し続けません。|Keep the inlet, fitting and idler open. After reaching temperature and waiting two minutes, feed fresh PLA straight down and check actual extrusion. Do not reassemble yet. Stop pushing if flow does not return.|Vstup, šroubení a idler ponechte otevřené. Po dosažení teploty a dvou minutách čekání zaveďte nové PLA přímo dolů a ověřte skutečnou extruzi. Zatím nic neuzavírejte. Pokud se tok neobnoví, přestaňte tlačit.|Einlass, Fitting und Idler offen lassen. Nach Erreichen der Temperatur zwei Minuten warten, frisches PLA gerade nach unten schieben und tatsächlichen Austritt prüfen. Noch nicht zusammenbauen. Ohne Fluss nicht weiterdrücken.')};
 feed.steps[5]={...feed.steps[5],id:'feed-result',title:l('PLAを抜いて、結果で進み先を選ぶ|Withdraw PLA and choose by the result|Vyjmout PLA a zvolit podle výsledku|PLA herausziehen und nach Ergebnis wählen'),body:l('開放を保って試したPLAを真上へ抜きます。実機で流れが戻り、PLAも抜けた場合だけ締め戻しへ進みます。抜けない場合は無理に引かず、詰まり対処へ戻ります。見える破片は破片の引抜きへ、ノズル内部の詰まりは交換手順へ。分解前は完全に冷却し、電源を切ってプラグを抜きます。|Keep access open and withdraw the test PLA straight upward. Reassemble only if actual flow returned and the PLA was removed. If it will not move, do not force it; return to blockage checks. Use fragment removal for a visible fragment or the nozzle procedure for an internal blockage. Cool completely, switch off and unplug before disassembly.|Přístup ponechte otevřený a zkušební PLA vytáhněte přímo vzhůru. Sestavujte pouze po obnovení skutečného toku a vyjmutí PLA. Pokud nejde vytáhnout, nepoužívejte sílu a vraťte se ke kontrole ucpání. Viditelný úlomek řešte vytažením, vnitřní ucpání postupem výměny trysky. Před rozebráním nechte zcela vychladnout, vypněte a odpojte napájení.|Zugang offen lassen und Test-PLA gerade nach oben herausziehen. Nur nach wiederhergestelltem Fluss und entferntem PLA zusammenbauen. Bei Widerstand keine Gewalt anwenden, zur Verstopfungsprüfung zurückkehren. Sichtbare Reste herausziehen, innere Verstopfung mit dem Düsenverfahren beheben. Vor Zerlegen vollständig abkühlen, ausschalten und Netzstecker ziehen.'),filamentChoices:[{step:6,label:FILAMENT_COPY.success},{task:'clog',label:FILAMENT_COPY.failure}],related:['fragment','nozzle']};
 const restore=(id,title,body,refs)=>({id,title:l(title),body:l(body),refs,source:manual,inspection:false});
 feed.steps.push(restore('feed-idler-close','流れが戻った場合：アイドラーを閉じる|If flow returned: close the idler|Po obnovení toku: zavřít idler|Bei wiederhergestelltem Fluss: Idler schließen','PLAを抜いた後、アイドラーを閉じてスイベルでロックします。|After removing PLA, close the idler and lock the swivel.|Po vyjmutí PLA zavřete idler a zajistěte otočný díl.|Nach Entfernen des PLA Idler schließen und Schwenkhebel verriegeln.',['idlerBearing1',798]),restore('feed-inlet-refit','外した継手とガイドを戻す|Refit the removed fitting and guide|Vrátit sejmuté šroubení a vodítko|Entferntes Fitting und Führung montieren','外した継手をねじ戻してガイドを下げます。通常のロードと吐出を実機で確認します。|Screw the removed fitting back in and lower the guide. Check normal loading and extrusion on the printer.|Zašroubujte sejmuté šroubení a spusťte vodítko. Na tiskárně ověřte běžné zavedení a extruzi.|Entferntes Fitting einschrauben und Führung absenken. Normales Laden und Extrusion am Drucker prüfen.',[817,'bowdenBend']));
 fragment.revision++;
 fragment.steps[0]={...fragment.steps[0],body:fragment.steps[0].body.map((s,i)=>s+'\n\n'+l('入口に継手が装着されている場合は、冷えた状態でガイドを持ち上げて継手を外し、引抜き経路を空けます。外した部品は最後に戻します。|If a fitting is installed at the inlet, lift the guide and remove the fitting while cold to clear the withdrawal path. Refit removed parts at the end.|Je-li na vstupu šroubení, za studena zvedněte vodítko a šroubení vyjměte, aby byla cesta pro vytažení volná. Nakonec sejmuté díly vraťte.|Falls am Einlass ein Fitting montiert ist, im kalten Zustand Führung anheben und Fitting entfernen, um den Zugweg freizuhalten. Entfernte Teile zum Schluss montieren.')[i]),supplementalSources:[...(fragment.steps[0].supplementalSources||[]),{url:manual,label:l('上部継手の取外し・復旧|Inlet fitting removal and refit|Vyjmutí a vrácení vstupního šroubení|Einlassfitting entfernen und montieren')}]};
 fragment.steps[2]={...fragment.steps[2],id:'fragment-pull'};
 fragment.steps.push(restore('fragment-inlet-refit','外した継手とガイドを戻す|Refit the removed fitting and guide|Vrátit sejmuté šroubení a vodítko|Entferntes Fitting und Führung montieren','破片を完全に除去した後、外した継手を戻しガイドを下げます。流れが戻ればコールドプルへ進みます。|After complete fragment removal refit the removed fitting and lower the guide. If flow is restored continue with cold pull.|Po úplném vyjmutí úlomku vraťte šroubení a spusťte vodítko. Po obnovení toku pokračujte cold pullem.|Nach vollständiger Entfernung Fitting montieren und Führung absenken. Bei wiederhergestelltem Fluss mit Cold Pull fortfahren.',[817,'bowdenBend']));
 fragment.steps.at(-1).related=fragment.steps[3].related;
 fragment.steps[3]={...fragment.steps[3],related:[],body:fragment.steps[3].body.map((s,i)=>s+'\n\n'+l('次の手順で外した継手とガイドを戻してから、結果に応じた処置へ進みます。|Refit the removed fitting and guide in the next step before choosing the next treatment.|V dalším kroku vraťte sejmuté šroubení a vodítko a teprve potom zvolte další postup.|Im nächsten Schritt entferntes Fitting und Führung montieren, erst danach die weitere Behandlung wählen.')[i])};

}
